import numpy as np


class SHADEPolishArchiveDEv6:
    """
    Feasibility-rule SHADE DE for mixed-integer constrained problems.
    Refinements over v5:
    - every new feasible best is polished by a budget-capped single-gene sweep, so exploitation
      follows improvements immediately instead of waiting for a stall;
    - local-move probability is floored higher while the feasible archive is small or stagnating;
    - the DE donor pbest is drawn partly from the feasible archive, so elites guide the population;
    - hashed evaluation cache (repeated points cost no budget).
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        class _Stop(Exception):
            pass

        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        d = len(lb)
        types = list(func.variable_types)
        cont = np.array([t == "continuous" for t in types], dtype=bool)
        cat = np.array([t == "categorical" for t in types], dtype=bool)
        ints = ~cont
        nv = np.ones(d, dtype=int)
        n_values = getattr(func, "n_values", None)
        if n_values is not None:
            for i in range(d):
                if ints[i]:
                    nv[i] = max(2, int(n_values[i]))
        span = ub - lb
        ci = np.where(cont)[0]
        ii = np.where(ints)[0]
        budget = self.budget

        cache = {}
        st = {"n": 0, "hits": 0, "best_f": np.inf, "best_x": None, "min_v": np.inf}
        archive = []       # feasible elites (f, x)
        inf_archive = []   # least-violating infeasible points (v, x)
        ARCH_MAX = 10
        INF_MAX = 10

        def repair(x):
            x = np.clip(x, lb, ub)
            if ii.size:
                x[ii] = np.clip(np.round(x[ii]), 0, nv[ii] - 1)
            return x

        def hamming_min(x, pool):
            if not pool:
                return d
            best = d
            for _, xa in pool:
                dist = np.sum(np.abs(xa[ii] - x[ii]) > 0.5) if ii.size else 0
                dist += np.sum(np.abs(xa[ci] - x[ci]) > 1e-9) if ci.size else 0
                if dist < best:
                    best = dist
            return best

        def add_archive(f, x):
            for _, xa in archive:
                if np.array_equal(xa, x):
                    return
            if archive and hamming_min(x, archive) == 0:
                return
            archive.append((f, x.copy()))
            archive.sort(key=lambda t: t[0])
            del archive[ARCH_MAX:]

        def add_inf(v, x):
            if not np.isfinite(v):
                return
            for _, xa in inf_archive:
                if np.array_equal(xa, x):
                    return
            inf_archive.append((v, x.copy()))
            inf_archive.sort(key=lambda t: t[0])
            del inf_archive[INF_MAX:]

        def evaluate(x):
            x = repair(np.array(x, dtype=float))
            k = x.tobytes()
            if k in cache:
                st["hits"] += 1
                if st["hits"] > 20000:
                    raise _Stop()
                return cache[k]
            if st["n"] >= budget:
                raise _Stop()
            st["n"] += 1
            st["hits"] = 0
            f, g = func(x)
            f = float(f)
            g = np.atleast_1d(np.asarray(g, dtype=float))
            if np.all(np.isfinite(g)):
                v = float(np.sum(np.maximum(g, 0.0)))
            else:
                v = np.inf
            if not np.isfinite(f):
                f = np.inf
            feas = (v <= 0.0) and np.isfinite(f)
            if (not feas) and v <= 0.0:
                v = 1e-12
            res = (x, f, v)
            cache[k] = res
            if feas:
                add_archive(f, x)
                if f < st["best_f"]:
                    st["best_f"] = f
                    st["best_x"] = x.copy()
            else:
                add_inf(v, x)
            if v < st["min_v"]:
                st["min_v"] = v
            return res

        def better(f1, v1, f2, v2):
            fe1, fe2 = v1 <= 0.0, v2 <= 0.0
            if fe1 and fe2:
                return f1 < f2
            if fe1 != fe2:
                return fe1
            return v1 < v2

        def key(ind):
            return (0, ind[1]) if ind[2] <= 0.0 else (1, ind[2])

        def random_int_value(k, cur=None):
            n = nv[k]
            if cur is None:
                return np.random.randint(n)
            r = np.random.randint(n - 1)
            return r + 1 if r >= cur else r

        def mutate_int_gene(y, k):
            n = nv[k]
            if n <= 1:
                return
            cur = int(round(y[k]))
            if n == 2:
                y[k] = 1 - cur
                return
            if cat[k]:
                y[k] = random_int_value(k, cur)
                return
            if np.random.rand() < 0.15:
                y[k] = np.random.randint(n)
                return
            step = 1 if np.random.rand() < 0.5 else -1
            nxt = cur + step
            if nxt < 0 or nxt > n - 1:
                nxt = cur - step
            y[k] = min(n - 1, max(0, nxt))

        def mutate_gene(y, k, scale=0.03):
            if cont[k]:
                y[k] += np.random.randn() * scale * span[k]
            else:
                mutate_int_gene(y, k)

        def local_move(x, m_max=3):
            y = x.copy()
            for _ in range(1 + np.random.randint(m_max)):
                mutate_gene(y, np.random.randint(d))
            return y

        def perturb(x, m_min=3, m_max=6):
            y = x.copy()
            for _ in range(m_min + np.random.randint(m_max - m_min + 1)):
                mutate_gene(y, np.random.randint(d), scale=0.1)
            return y

        def lhs(n):
            X = np.empty((n, d))
            for j in range(d):
                if cont[j]:
                    u = (np.random.permutation(n) + np.random.rand(n)) / n
                    X[:, j] = lb[j] + u * span[j]
                else:
                    X[:, j] = np.random.randint(0, nv[j], size=n)
            return X

        def capped_sweep(x0, cap):
            """Greedy single-gene sweep, stopping after roughly `cap` new evaluations."""
            start = st["n"]
            cur = evaluate(x0)
            improved = True
            while improved and st["n"] - start < cap:
                improved = False
                for k in np.random.permutation(d):
                    if st["n"] - start >= cap:
                        break
                    xc, fc, vc = cur
                    if cont[k]:
                        for _ in range(2):
                            y = xc.copy()
                            y[k] += np.random.randn() * 0.02 * span[k]
                            cand = evaluate(y)
                            if better(cand[1], cand[2], fc, vc):
                                cur = cand
                                improved = True
                                break
                        continue
                    cv = int(round(xc[k]))
                    if cat[k] or nv[k] == 2:
                        vals = [t for t in range(nv[k]) if t != cv]
                    else:
                        vals = [t for t in (cv - 1, cv + 1, cv - 2, cv + 2)
                                if 0 <= t < nv[k]]
                    for t in vals:
                        if st["n"] - start >= cap:
                            break
                        y = xc.copy()
                        y[k] = t
                        cand = evaluate(y)
                        if better(cand[1], cand[2], fc, vc):
                            cur = cand
                            improved = True
                            break
            return cur

        def sweep(x0):
            return capped_sweep(x0, cap=10 ** 9)

        def pair_sweep(x0, n_eval):
            """Pair moves on integer genes; ordinal-neighbour pairs are favoured."""
            cur = evaluate(x0)
            if ii.size < 2:
                return cur
            fails = 0
            for _ in range(n_eval):
                xc, fc, vc = cur
                y = xc.copy()
                p1 = np.random.randint(ii.size)
                k1 = ii[p1]
                if (not cat[k1]) and np.random.rand() < 0.5:
                    p2 = int(np.clip(p1 + (1 if np.random.rand() < 0.5 else -1), 0, ii.size - 1))
                    if p2 == p1:
                        p2 = (p1 + 1) % ii.size
                    k2 = ii[p2]
                else:
                    k2 = ii[np.random.randint(ii.size)]
                    while k2 == k1:
                        k2 = ii[np.random.randint(ii.size)]
                mutate_int_gene(y, k1)
                mutate_int_gene(y, k2)
                if ci.size and np.random.rand() < 0.3:
                    kc = ci[np.random.randint(ci.size)]
                    y[kc] += np.random.randn() * 0.02 * span[kc]
                cand = evaluate(y)
                if better(cand[1], cand[2], fc, vc):
                    cur = cand
                    fails = 0
                else:
                    fails += 1
                    if fails > max(6, d):
                        break
            return cur

        def local_search(x0):
            cur = sweep(x0)
            for _ in range(3):
                prev = cur
                cur = pair_sweep(cur[0], n_eval=2 * d)
                cur = sweep(cur[0])
                if not better(cur[1], cur[2], prev[1], prev[2]):
                    break
            return cur

        # success-history memory
        H = 6
        MF = np.full(H, 0.5)
        MCR = np.full(H, 0.5)
        mem_k = 0

        def sample_F(m):
            for _ in range(20):
                F = m + 0.1 * np.tan(np.pi * (np.random.rand() - 0.5))
                if F > 0:
                    return min(F, 1.0)
            return 0.1

        def sample_CR(m):
            return float(np.clip(m + 0.1 * np.random.randn(), 0.0, 1.0))

        mu = max(12, min(40, 2 * d))
        n0 = max(mu, min(15 * d, budget // 3))
        n0 = min(n0, budget)
        p_top = max(2, int(0.2 * mu))
        p_local = 0.1
        s_loc, t_loc = 0.0, 0.0
        stall_limit = max(10, min(20, 8 + d // 2))
        restart_count = 0
        anchor_ptr = 0
        polish_seen = np.inf
        polish_cap = 3 * d

        try:
            pop = []
            for x in lhs(n0):
                xe, f, v = evaluate(x)
                pop.append((xe, f, v, 0.5, 0.9))
            pop = sorted(pop, key=key)[:mu]

            last_best = st["best_f"]
            last_v = st["min_v"]
            stall = 0

            while True:
                if st["hits"] > 300:
                    xe, f, v = evaluate(np.array(
                        [np.random.rand() * span[j] + lb[j] if cont[j]
                         else np.random.randint(nv[j]) for j in range(d)],
                        dtype=float))
                    pop = sorted(pop + [(xe, f, v, 0.5, 0.9)], key=key)[:mu]
                    st["hits"] = 0

                pop = sorted(pop, key=key)
                n = len(pop)
                new_pop = []
                S_F, S_CR, S_w = [], [], []
                gen_loc_t, gen_loc_s = 0, 0
                for i in range(n):
                    x_i, f_i, v_i, _, _ = pop[i]
                    r = np.random.randint(H)
                    Fi = sample_F(MF[r])
                    CRi = sample_CR(MCR[r])
                    is_loc = False

                    if archive and np.random.rand() < p_local:
                        is_loc = True
                        base = archive[np.random.randint(len(archive))][1]
                        trial = local_move(base)
                    else:
                        # pbest donor: from population top, sometimes from feasible archive
                        if archive and np.random.rand() < 0.3:
                            pb = archive[np.random.randint(min(3, len(archive)))][1]
                        else:
                            pb = pop[np.random.randint(min(p_top, n))][0]
                        cand_idx = [j for j in range(n) if j != i]
                        r1, r2 = np.random.choice(cand_idx, 2, replace=False)
                        x_r1 = pop[r1][0]
                        x_r2 = pop[r2][0]
                        donor = x_i.copy()
                        if ci.size:
                            dc = x_i[ci] + Fi * (pb[ci] - x_i[ci]) + Fi * (x_r1[ci] - x_r2[ci])
                            lo = lb[ci]
                            hi = ub[ci]
                            xc = x_i[ci]
                            dc = np.where(dc < lo, 0.5 * (xc + lo), dc)
                            dc = np.where(dc > hi, 0.5 * (xc + hi), dc)
                            donor[ci] = dc
                        if ii.size:
                            pick = np.random.rand(ii.size) < 0.5
                            c_int = np.where(pick, pb[ii], x_r1[ii])
                            rr = np.random.rand(ii.size)
                            c_cat = np.where(rr < 1.0 / 3, pb[ii],
                                             np.where(rr < 2.0 / 3, x_r1[ii], x_r2[ii]))
                            donor[ii] = np.where(cat[ii], c_cat, c_int)
                            pm = min(1.0, 1.5 / ii.size)
                            for k in ii:
                                if np.random.rand() < pm:
                                    mutate_int_gene(donor, k)
                        mask = np.random.rand(d) < CRi
                        mask[np.random.randint(d)] = True
                        trial = np.where(mask, donor, x_i)

                    xe, f_t, v_t = evaluate(trial)
                    if is_loc:
                        gen_loc_t += 1
                    if better(f_t, v_t, f_i, v_i):
                        if is_loc:
                            gen_loc_s += 1
                        new_pop.append((xe, f_t, v_t, Fi, CRi))
                        if np.isfinite(f_i) and np.isfinite(f_t) and v_i <= 0 and v_t <= 0:
                            delta = max(f_i - f_t, 1e-12)
                        else:
                            diff = v_i - v_t
                            delta = max(diff, 1e-12) if np.isfinite(diff) else 1.0
                        S_F.append(Fi)
                        S_CR.append(CRi)
                        S_w.append(delta)
                    else:
                        new_pop.append(pop[i])

                # credit-assigned local-move rate, floored higher while the archive is small
                if gen_loc_t > 0:
                    s_loc = 0.7 * s_loc + gen_loc_s
                    t_loc = 0.7 * t_loc + gen_loc_t
                floor = 0.1 if len(archive) >= 5 else 0.15
                p_local = float(np.clip(
                    floor + 0.3 * (s_loc + 1.0) / (t_loc + 3.0), floor, 0.4))

                if S_F:
                    w = np.asarray(S_w)
                    w = w / w.sum()
                    sF = np.asarray(S_F)
                    sC = np.asarray(S_CR)
                    mF = np.sum(w * sF * sF) / max(np.sum(w * sF), 1e-12)
                    mC = np.sum(w * sC)
                    MF[mem_k] = np.clip(mF, 0.0, 1.0)
                    MCR[mem_k] = np.clip(mC, 0.0, 1.0)
                    mem_k = (mem_k + 1) % H

                pop = sorted(new_pop, key=key)[:mu]

                # polish every new feasible best immediately (capped)
                if st["best_f"] < polish_seen - 1e-12 and st["best_x"] is not None:
                    polish_seen = st["best_f"]
                    sw = capped_sweep(st["best_x"], cap=polish_cap)
                    if sw[2] <= 0.0 and np.isfinite(sw[1]) and sw[1] < polish_seen - 1e-12:
                        polish_seen = sw[1]
                    pop = sorted(pop + [(sw[0], sw[1], sw[2], 0.5, 0.9)], key=key)[:mu]

                improved = False
                if st["best_f"] < last_best - 1e-12:
                    last_best = st["best_f"]
                    improved = True
                if st["best_f"] == np.inf and st["min_v"] < last_v - 1e-12:
                    last_v = st["min_v"]
                    improved = True
                if st["best_f"] < np.inf:
                    last_v = st["min_v"]
                stall = 0 if improved else stall + 1

                if stall >= stall_limit:
                    restart_count += 1
                    # 1) anchor: rotate over feasible archive, else least-violating points
                    if archive:
                        anchor = archive[anchor_ptr % len(archive)][1]
                        anchor_ptr += 1
                        if np.random.rand() < 0.3:
                            anchor = archive[np.random.randint(len(archive))][1]
                    elif inf_archive:
                        anchor = inf_archive[min(len(inf_archive) - 1,
                                                 np.random.randint(min(3, len(inf_archive))))][1]
                    else:
                        anchor = pop[0][0]
                    sw = local_search(anchor)
                    pop = sorted(pop + [(sw[0], sw[1], sw[2], 0.5, 0.9)], key=key)[:mu]

                    # 2) elite-preserving partial restart; stronger shake while infeasible
                    feas_known = len(archive) > 0
                    n_keep = max(2, int(0.3 * mu)) if feas_known else max(1, int(0.15 * mu))
                    keep = pop[:n_keep]
                    n_fresh = mu - n_keep
                    n_pert = n_fresh // 2 if feas_known else (2 * n_fresh) // 3
                    shake = 3 if feas_known else 3 + min(4, restart_count // 3)
                    fresh = []
                    for x in lhs(n_fresh - n_pert):
                        xe, f, v = evaluate(x)
                        fresh.append((xe, f, v, 0.5, 0.9))
                    pool = archive if archive else inf_archive
                    if pool:
                        top = min(3, len(pool))
                        for _ in range(n_pert):
                            base = pool[np.random.randint(top)][1]
                            xe, f, v = evaluate(perturb(base, m_min=shake, m_max=shake + 3))
                            fresh.append((xe, f, v, 0.5, 0.9))
                    else:
                        for x in lhs(n_pert):
                            xe, f, v = evaluate(x)
                            fresh.append((xe, f, v, 0.5, 0.9))
                    pop = sorted(keep + fresh, key=key)
                    stall = 0
                    last_best = st["best_f"]
                    last_v = st["min_v"]
        except _Stop:
            pass

        if st["best_x"] is None:
            return np.inf, None
        return st["best_f"], st["best_x"]
